//! Regenerate the embedded context-pack table from the asset tree.

use std::fs;
use std::path::Path;

use crate::error::{Error, io_err};

const HEADER: &str = "\
// Generated by cargo xtask generate-context-packs. Do not edit.
// Derived from openrig packages/daemon/context-packs-src (v0.6.9, Apache-2.0); ported to Rust and modified.

/// Relative path and bytes for each shipped pack file.
pub(super) static FILES: &[(&str, &[u8])] = &[
";

/// Rewrite `builtin_gen.rs`, or fail when `--check` and the file would change.
///
/// # Errors
///
/// Returns [`Error`] when the asset tree or the generated file cannot be read
/// or written.
pub fn generate(root: &Path, check: bool) -> Result<(), Error> {
    let assets = root.join("crates/crewmux-orchestration/assets/context-packs");
    let dest = root.join("crates/crewmux-orchestration/src/context_packs/builtin_gen.rs");
    let mut files = Vec::new();
    walk(&assets, &assets, &mut files)?;
    files.sort();
    let mut text = String::from(HEADER);
    for rel in &files {
        text.push_str("    (\n        \"");
        text.push_str(rel);
        text.push_str("\",\n        include_bytes!(\"../../assets/context-packs/");
        text.push_str(rel);
        text.push_str("\"),\n    ),\n");
    }
    text.push_str("];\n");
    if check {
        let current = fs::read_to_string(&dest)
            .map_err(|source| io_err(format!("read {}", dest.display()), source))?;
        if current != text {
            return Err(Error::Message(
                "builtin_gen.rs does not match the asset tree; run cargo xtask generate-context-packs"
                    .to_owned(),
            ));
        }
        return Ok(());
    }
    fs::write(&dest, text).map_err(|source| io_err(format!("write {}", dest.display()), source))?;
    Ok(())
}

fn walk(root: &Path, dir: &Path, out: &mut Vec<String>) -> Result<(), Error> {
    let entries =
        fs::read_dir(dir).map_err(|source| io_err(format!("read {}", dir.display()), source))?;
    for entry in entries {
        let entry = entry.map_err(|source| io_err(format!("read {}", dir.display()), source))?;
        let path = entry.path();
        let kind = entry
            .file_type()
            .map_err(|source| io_err(format!("stat {}", path.display()), source))?;
        if kind.is_dir() {
            walk(root, &path, out)?;
        } else if kind.is_file() {
            out.push(relative(root, &path)?);
        }
    }
    Ok(())
}

fn relative(root: &Path, path: &Path) -> Result<String, Error> {
    let rel = path
        .strip_prefix(root)
        .map_err(|_| Error::Message(format!("{} is outside {}", path.display(), root.display())))?;
    let mut text = String::new();
    for (index, component) in rel.components().enumerate() {
        if index > 0 {
            text.push('/');
        }
        text.push_str(&component.as_os_str().to_string_lossy());
    }
    if text.is_empty() {
        return Err(Error::Message(format!(
            "empty relative path for {}",
            path.display()
        )));
    }
    Ok(text)
}
